+func dumbJoin(names ...string) string {
+	if len(names) == 0 {
+		return string(os.PathSeparator)
+	}
+	result := ""
+	for _, n := range names {
+		if result != "" {
+			result = result + string(os.PathSeparator)
+		}
+		result = result + n
+	}
+	return result

